function minSumMaxPartitions(A, k) {
  const n = A.length;
  const INF = 1e15;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(INF));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      let mx = -Infinity;
      for (let j = i - 1; j >= 0; j--) {
        mx = Math.max(mx, A[j]);
        if (dp[j][t - 1] !== INF) {
          dp[i][t] = Math.min(dp[i][t], dp[j][t - 1] + mx);
        }
      }
    }
  }
  return dp[n][k];
}
```

